def transform(grid):
    out = [row[:] for row in grid]
    # Fill the interiors of the diagonal wedges.
    for r, cols in {0: range(3, 8), 1: (2, 4, 5, 6), 2: (1, 2, 3, 5), 3: (0, 1, 2, 3, 4)}.items():
        for c in cols:
            if out[r][c] == 0:
                out[r][c] = 2
    return out
